const repo = new MensajesRepository();
const ROLES = ["Administrador", "Recepcion"];
const MODES = new Set(["manual", "assistant", "paused", "review_required"]);
const id = (value) => Number.isInteger(Number(value)) && Number(value) > 0;
const text = (value) => typeof value === "string" && value.trim().length > 0;
// Quita la marca interna " — verificar..." del comentario para que no llegue al paciente en recordatorios.
const cleanTreatment = (value) => String(value || "").replace(/\s*[—-]\s*verificar\b.*$/i, "").trim();
const fillReminder = (template, values) => String(template).replace(/{{\s*([^}]+)\s*}}/g, (_, key) => String(values[key.trim()] ?? ""));
// Familiares con el mismo número y cita el mismo día reciben UN solo recordatorio (decisión 2026-10-07): los
// valores de la plantilla se juntan ("Daniela … y Tatiana …"); si la hora o el tratamiento difieren, cada uno
// lleva el primer nombre entre paréntesis. Cada cita conserva su fila y su estado; el runtime manda el mensaje
// una sola vez por número (mismo teléfono y mismo texto dentro del lote).
const joinList = (list) => (list.length > 1 ? `${list.slice(0, -1).join(", ")} y ${list[list.length - 1]}` : list[0] || "");
const groupByPhone = (items) => { const groups = new Map(); for (const x of items) groups.set(x.phone, [...(groups.get(x.phone) || []), x]); return groups; };
function reminderGroupValues(group) {
  const names = [...new Set(group.map((x) => String(x.patientName || "").trim()))];
  const perPerson = (pick) => {
    const vals = group.map(pick);
    if (new Set(vals).size === 1) return vals[0];
    return joinList(group.map((x, i) => (names.length > 1 ? `${vals[i]} (${String(x.patientName).trim().split(/\s+/)[0]})` : vals[i])));
  };
  return { nombre: joinList(names), hora: perPerson((x) => to12h(x.time)), tratamiento: perPerson((x) => cleanTreatment(x.treatment)) };
}
function allowed(req, res) { if (!ROLES.includes(req.user?.rol)) { res.status(403).json({ ok: false, message: "No tiene permiso para usar Mensajes" }); return false; } return true; }
function bad(res, message) { return res.status(400).json({ ok: false, message }); }
function resumeAssistantQueue(conversationId = null) { if (!repo.getAutomationSettings().enabled) return []; return repo.enqueueUnansweredAssistantMessages(repo.getGlobalSettings().responseGroupDelaySeconds, 100, conversationId); }
exports.metrics = (req, res) => { if (!allowed(req, res)) return; res.json({ ok: true, metrics: getMetrics() }); };
exports.searchPatients = async (req, res) => {
  if (!allowed(req, res)) return;
  const query = String(req.query?.q || "").trim();
  if (query.length < 2) return res.json({ ok: true, patients: [] });
  try {
    const digits = query.replace(/\D/g, "");
    const like = `%${query}%`;
    const [rows] = await pool.query("SELECT idPaciente, NombreP, telefonoP, estadoP, tipoTratamientoP FROM paciente WHERE NombreP LIKE ? OR (? <> '' AND REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(IFNULL(telefonoP,''),' ',''),'-',''),'(',''),')',''),'+',''),'.','') LIKE ?) ORDER BY estadoP DESC, NombreP LIMIT 20", [like, digits, `%${digits}%`]);
    res.json({ ok: true, patients: rows.map((p) => ({ id: p.idPaciente, name: p.NombreP, phone: p.telefonoP || "", active: Number(p.estadoP ?? 1) === 1, treatment: p.tipoTratamientoP || null })) });
  } catch (error) { res.status(500).json({ ok: false, message: "No se pudieron buscar pacientes" }); }
};
