exports.simulateIncoming = (req, res) => { if (!allowed(req, res)) return; let phone; try { phone = normalizePhone(req.body?.phone); } catch { return bad(res, "Telefono invalido"); } const message = req.body?.message; if (typeof message !== "string" || !message.trim()) return bad(res, "Mensaje obligatorio"); const result = repo.saveIncomingMessage({ externalId: `sim-in-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, phone, waChatId: `simulated:${phone}`, waContactNumber: phone, text: message.trim(), messageAt: new Date().toISOString() }); const queued = enqueueIncomingResponse(result.conversation.id, result.message.id, message.trim()); res.status(201).json({ ok: true, simulated: true, conversation: repo.getConversation(result.conversation.id), message: result.message, batchId: queued?.id || null, queued: Boolean(queued), observerMode: true }); };
// Modos:
//  - 'assistant' ("Pasar todo a IA"): fuerza cada conversación (incluida manual/revisión)
//    a modo IA y reencola los mensajes pendientes.
//  - 'paused' ("Pausar IA"): apaga la automatización y cancela los lotes en curso.
//  - 'resume' ("Reanudar IA"): solo vuelve a encender la automatización. No cambia el
//    modo de ninguna conversación ni reencola mensajes viejos; la IA retoma con los
//    mensajes que lleguen a partir de ahora (analizando el chat completo, como siempre).
exports.setGlobalAiMode = (req, res) => { if (!allowed(req, res)) return; const mode = req.body?.mode; if (!['assistant','paused','resume'].includes(mode)) return bad(res, "Modo IA invalido"); const settings = repo.getAutomationSettings(); repo.updateAutomationSettings({ ...settings, enabled: mode !== 'paused' }); let resumed = []; if (mode === 'assistant') { repo.db.prepare("UPDATE conversations SET attention_mode='assistant', human_owner_id=NULL, updated_at=datetime('now') WHERE attention_mode IN ('manual','paused','review_required')").run(); resumed = resumeAssistantQueue(); } else if (mode === 'paused') repo.db.prepare("UPDATE response_queue SET status='cancelled', error='IA pausada globalmente', updated_at=datetime('now') WHERE status IN ('generating','ready_to_send','sending')").run(); res.json({ ok: true, mode, settings: repo.getAutomationSettings(), resumedCount: resumed.length }); };
