exports.updateReminderSettings = (req, res) => { if (!allowed(req, res)) return; const template = req.body?.template; const minDelaySeconds = Number(req.body?.minDelaySeconds); const maxDelaySeconds = Number(req.body?.maxDelaySeconds); if (!text(template) || !Number.isFinite(minDelaySeconds) || !Number.isFinite(maxDelaySeconds) || minDelaySeconds < 1 || maxDelaySeconds < minDelaySeconds || maxDelaySeconds > 3600) return bad(res, "Configuracion de recordatorios invalida"); const allowedVars = new Set(["nombre", "fecha", "hora", "tratamiento"]); if ([...String(template).matchAll(/{{\s*([^}]+)\s*}}/g)].some((m) => !allowedVars.has(m[1].trim()))) return bad(res, "La plantilla contiene una variable no permitida"); res.json({ ok: true, settings: repo.updateReminderSettings({ template: String(template).trim(), minDelaySeconds, maxDelaySeconds }) }); };
exports.updateSettings = (req, res) => { if (!allowed(req, res)) return; const min = Number(req.body?.responseDelayMin); const max = Number(req.body?.responseDelayMax); const groupDelay = req.body?.responseGroupDelaySeconds === undefined ? null : Number(req.body.responseGroupDelaySeconds); const mode = req.body?.automationPhoneMode; const numbers = req.body?.automationPhoneNumbers; const ignoredTexts = req.body?.ignoredOutgoingTexts; if (!Number.isFinite(min) || !Number.isFinite(max) || min < 0 || max < min || max > 3600 || (groupDelay !== null && (!Number.isFinite(groupDelay) || groupDelay < 0 || groupDelay > 120))) return bad(res, "Rango de respuesta invalido"); if (mode !== undefined && !["all", "exclude", "allow_only"].includes(mode)) return bad(res, "Modo de telefonos invalido"); if (numbers !== undefined && (!Array.isArray(numbers) || numbers.some((phone) => !/^\d{7,20}$/.test(String(phone))))) return bad(res, "Lista de telefonos invalida"); if (ignoredTexts !== undefined && (!Array.isArray(ignoredTexts) || ignoredTexts.length > 20 || ignoredTexts.some((entry) => typeof entry !== "string" || !entry.trim() || entry.length > 500))) return bad(res, "Lista de mensajes ignorados invalida"); res.json({ ok: true, settings: repo.updateGlobalSettings(min, max, mode, numbers, groupDelay, ignoredTexts !== undefined ? ignoredTexts.map((t) => t.trim()) : null) }); };
