exports.testAiProviderConnection = async (req, res) => {
  if (!allowed(req, res)) return;
  const config = repo.getAiProviderSecret();
  const started = Date.now();
  const headers = { "Content-Type": "application/json", ...(config.apiKey ? { Authorization: `Bearer ${config.apiKey}` } : {}) };
  const request = async (path, options = {}) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), config.timeoutMs);
    try { return await fetch(`${config.baseUrl.replace(/\/$/, "")}${path}`, { ...options, headers: { ...headers, ...(options.headers || {}) }, signal: controller.signal }); }
    finally { clearTimeout(timer); }
  };
  try {
    const models = await request("/models");
    const modelsPayload = await models.json().catch(() => ({}));
    if (!models.ok) return res.status(502).json({ ok: false, connected: false, stage: "models", message: `Proveedor IA HTTP ${models.status}: ${modelsPayload.error?.message || modelsPayload.message || "no respondió correctamente"}`, durationMs: Date.now() - started });
    const completion = await request("/chat/completions", { method: "POST", body: JSON.stringify({ model: config.model, temperature: 0, messages: [{ role: "user", content: "Responde únicamente: OK" }] }) });
    const completionPayload = await completion.json().catch(() => ({}));
    if (!completion.ok) return res.status(502).json({ ok: false, connected: false, stage: "chat_completions", message: `Proveedor IA HTTP ${completion.status}: ${completionPayload.error?.message || completionPayload.message || "no pudo generar respuesta"}`, durationMs: Date.now() - started });
    const answer = completionPayload.choices?.[0]?.message?.content;
    if (typeof answer !== "string" || !answer.trim()) return res.status(502).json({ ok: false, connected: false, stage: "chat_completions", message: "El proveedor no devolvió contenido en chat/completions", durationMs: Date.now() - started });
    res.json({ ok: true, connected: true, stage: "chat_completions", providerMode: config.providerMode, model: config.model, durationMs: Date.now() - started });
  } catch (error) {
    const detail = error?.name === "AbortError" ? `Tiempo de conexión agotado (${config.timeoutMs} ms)` : `${error?.cause?.code || error?.cause?.message || error?.message || String(error)}`;
    res.status(502).json({ ok: false, connected: false, stage: "network", message: `No se pudo conectar con el proveedor IA: ${detail}`, durationMs: Date.now() - started });
  }
};
